function fb.keyName(lrc)
if lrc==Itc[1730]then
return Itc[3928]
end
if lrc==Itc[1734]then
return Itc[3929]
end
if lrc==Itc[1761]then
return Itc[3930]
end
local mrc,nrc,orc=tostring(lrc):match(Itc[3931])
if not nrc then
return tostring(lrc)
end
return(({st=Itc[3932],rd=Itc[3933],ev=Itc[3934],inf=Itc[3935]})[mrc]or Itc[369])..O.levelName(nrc)..((orc and orc~=Itc[369])and(Itc[1584]..orc)or Itc[369])
end
function fb.plainMode(prc)
return string.format(Itc[3936],prc.label,(prc.p or 0)*100,prc.score or 0)
