function fb.upNext(qrc,rrc)
if not qrc then
return Itc[3937],Itc[369]
end
if j.where==Itc[1508]and qrc.kind==Itc[1475]and qrc.first and qrc.key==Q.key then
local trc=Itc[3938]
local urc,vrc=pcall(H.PSC.get_next_story_level,qrc.level)
if I.onlyStory and urc and vrc then
return O.levelName(vrc)..Itc[1738]..tostring(qrc.diff)..Itc[1739],Itc[3939]..trc
end
if rrc then
return fb.plainMode(rrc),Itc[3940]..trc
end
end
return fb.plainMode(qrc),qrc.why or Itc[369]
end
function fb.update()
local wrc=fb.COL or{}
local xrc=H.prof()or{}
if fb.nowCard then
local yrc
if not I.master then
yrc={icon=Itc[3941],title=Itc[3942],text=Itc[3943],sub=Itc[369],tag=Itc[369],progress=false,color=wrc.sub}
elseif j.where==Itc[1508]and Q.ld then
local zrc=O.levelName(Q.ld.id or Itc[1658])..(Q.ld._difficulty and(Itc[1738]..Q.ld._difficulty..Itc[1739])or Itc[369])
local Arc=Q.pressure or 0
local Brc=(J.pending and J.pending.key==Q.key and J.pending.label)and Itc[3944]or Itc[3945]
local Crc=Q.depth or{}
local Drc=(Crc.units or 0)>0 and M.clamp(Crc.covEnd or 0.6,0.1,1)or 0.6
